'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );


// MAIN //

/**
* Generates a companion matrix using accessor arrays.
*
* @private
* @param {NonNegativeInteger} N - number of indexed elements in `x`
* @param {Object} x - input array object
* @param {Collection} x.data - input array data
* @param {Array<Function>} x.accessors - array element accessors
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Object} out - output array object
* @param {Collection} out.data - output array data
* @param {Array<Function>} out.accessors - array element accessors
* @param {integer} strideOut1 - stride length for the first dimension of `out`
* @param {integer} strideOut2 - stride length for the second dimension of `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @returns {Object} output array object
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* var x = [ 1.0, 2.0, 3.0 ];
* var out = [ 0.0, 0.0, 0.0, 0.0 ];
*
* gcompanion( 3, arraylike2object( toAccessorArray( x ) ), 1, 0, arraylike2object( toAccessorArray( out ) ), 2, 1, 0 );
* // out => [ -2.0, -3.0, 1.0, 0.0 ]
*/
function gcompanion( N, x, strideX, offsetX, out, strideOut1, strideOut2, offsetOut ) { // eslint-disable-line max-len
	var xbuf;
	var obuf;
	var getX;
	var oset;
	var ix;
	var io;
	var ij;
	var M;
	var v;
	var i;
	var j;

	// Cache references to array data:
	xbuf = x.data;
	obuf = out.data;

	// Cache references to element accessors:
	getX = x.accessors[ 0 ];
	oset = out.accessors[ 1 ];

	M = N - 1;

	// Cache the leading coefficient:
	v = getX( xbuf, offsetX );

	ix = offsetX + strideX;
	io = offsetOut;
	if ( isRowMajor( [ strideOut1, strideOut2 ] ) ) {
		// Fill the first row with the remaining coefficients negated and normalized by the leading coefficient...
		ij = io;
		for ( j = 0; j < M; j++ ) {
			oset( obuf, ij, -getX( xbuf, ix ) / v );
			ix += strideX;
			ij += strideOut2;
		}
		// Fill the remaining rows with ones along the first subdiagonal and zeros elsewhere...
		for ( i = 1; i < M; i++ ) {
			io += strideOut1;
			ij = io;
			for ( j = 0; j < M; j++ ) {
				if ( j === i-1 ) {
					oset( obuf, ij, 1.0 );
				} else {
					oset( obuf, ij, 0.0 );
				}
				ij += strideOut2;
			}
		}
		return out;
	}
	// Column-major: fill each column with a normalized coefficient negated in the first row, a one along the first subdiagonal, and zeros elsewhere...
	for ( j = 0; j < M; j++ ) {
		ij = io;
		oset( obuf, ij, -getX( xbuf, ix ) / v );
		for ( i = 1; i < M; i++ ) {
			ij += strideOut1;
			if ( i === j+1 ) {
				oset( obuf, ij, 1.0 );
			} else {
				oset( obuf, ij, 0.0 );
			}
		}
		ix += strideX;
		io += strideOut2;
	}
	return out;
}


// EXPORTS //

module.exports = gcompanion;
